/bin/zsh -lc "python3 build_answer.py && python3 - <<'PY'
import json,re,collections,xml.etree.ElementTree as ET
s=json.load(open('source.json')); a=json.load(open('answer.json'))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
assert len(a)==len(s)==9
for x,y in zip(s,a):
 assert set(y)=={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
 for k in ['code_id','source_id','source_sha256','number']: assert x[k]==y[k]
 assert y['status']=='rewrite_draft' and y['proposed_xml']
 t=ET.fromstring('<root>'+y['proposed_xml']+'</root>')
 for e in t.iter():
  if e.tag=='root': continue
  assert e.tag in allowed
  assert all(k in {'rowspan','colspan'} and re.fullmatch(r'\\d+',v) for k,v in e.attrib.items())
 def nums(z): return collections.Counter(re.findall(r'\\d+(?:[ -]\\d+)*(?:\\s*%)?',re.sub('<["'^>]*>'"',' ',z)))
 def refs(z): return collections.Counter(re.findall(r'\\b[LDR]\\.\\s*\\d+[\\w-]*',z))
 print(x['number'], 'p:',len(re.findall('<p[ >]',x['source_xml'])),len(t.findall('p')), 'caractères:',len(x['source_xml']),len(y['proposed_xml']))
 for title,func in [('Chiffres',nums),('Renvois',refs)]:
  old,new=func(x['source_xml']),func(y['proposed_xml'])
  if old"'!=new: print(title,'"'absents:',dict(old-new),'ajoutés:',dict(new-old))
print('Structure JSON, identifiants et XML : conformes')
PY"

