/bin/zsh -lc "python3 - <<'PY'
import json,re,collections,xml.etree.ElementTree as ET
from pathlib import Path
sources=json.loads(Path('source.json').read_text())
answers=json.loads(Path('answer.json').read_text())
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
keys={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
def paragraphs(xml):
 p=re.findall(r'<p["'^>]*>(.*?)</p>'"',xml,re.S)
 return p or [x.strip() for x in re.split(r'<br\\s*/?>',xml) if x.strip()]
def figures(xml):
 return collections.Counter(re.findall(r'\\d+(?:[ -]\\d+)*(?:\\s*%)?',re.sub('<["'^>]+>'"',' ',xml)))
def references(xml):
 return collections.Counter(re.findall(r'\\b[LDR]\\.\\s*\\d+[\\w-]*',xml))
def labels(xml):
 return re.findall(r'(?:"'^|>|'"\\n)\\s*(\\d+°(?:\\s+(?:bis|ter|quater))?|[ab]\\))',xml)
assert len(sources)==len(answers)==9
assert len({x['source_id'] for x in answers})==9
for source,answer in zip(sources,answers):
 assert set(answer)==keys
 assert all(answer[k]==source[k] for k in ['code_id','source_id','source_sha256','number'])
 assert answer['status']=='rewrite_draft'
 assert all(isinstance(answer[k],str) and answer[k] for k in ['proposed_xml','reason','review_notes'])
 root=ET.fromstring('<root>'+answer['proposed_xml']+'</root>')
 for elem in list(root.iter())[1:]:
  assert elem.tag in allowed
  assert all(k in {'rowspan','colspan'} and re.fullmatch(r'\\d+',v) for k,v in elem.attrib.items())
 old,new=paragraphs(source['source_xml']),paragraphs(answer['proposed_xml'])
 assert len(old)==len(new),(source['number'],'alinéas')
 for i,(x,y) in enumerate(zip(old,new),1):
  assert figures(x)==figures(y),(source['number'],i,'chiffres')
  assert references(x)==references(y),(source['number'],i,'renvois')
 assert labels(source['source_xml'])==labels(answer['proposed_xml']),(source['number'],'subdivisions')
 assert answer['proposed_xml'].count('<table')==source['source_xml'].count('<table')
 assert not re.search(r'texte inchangé|\\[\\.\\.\\.\\]|à compléter|résumé',answer['proposed_xml'],re.I)
 print(source['number']+': texte intégral, alinéas, chiffres, renvois, subdivisions et balises contrôlés')
print('Validation finale : 9 objets conformes ; answer.json,',Path('answer.json').stat().st_size,'octets.')
print('\\nPASSAGES CORRIGÉS RELUS :')
for i,needles in {0:['où ils disposent'],1:['chaque année.','L\\'Union sociale'],2:['L. 615-1 ou situés','destinés à être occupés par','porter atteinte','doivent être réalisées à un prix'],3:[\"dans un délai d'un an\",\"ni de la compétence\"],5:['nécessite une solution']}.items():
 for p in paragraphs(answers[i]['proposed_xml']):
  if any(n in p for n in needles): print(answers[i]['number'],p)
